"""Complete eight distinct mayonnaise and cooked dressing recipes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r

r=add(0,'Australian Two-Yolk Vinegar Mayonnaise',12,20,'A tangy, relatively loose mayonnaise made with two yolks and a generous amount of vinegar.',[yolks(2),oil(140),vinegar(70),salt(.25)],['Set a clean small bowl on a damp towel. Whisk {{yolks}} and {{salt}} until smooth.','Measure {{oil}} into a jug and whisk it into the yolks drop by drop. Once thick and glossy, add the remaining oil in a thin stream, whisking continuously.','Gradually whisk in {{vinegar}}, a teaspoon at a time, stopping each time until it is incorporated. This generous vinegar proportion makes a pourable dressing rather than a stiff sandwich mayonnaise.',COLD],'The source one gill oil and half-gill vinegar are interpreted using a rounded Imperial-style 140 ml and 70 ml. These are disclosed modern working amounts, not a claim that every historical gill had this volume. Only the egg yolks are used. The late vinegar addition is retained; salt and portion count are supplied.');eggsource(r)
r=add(1,'Australian Mustard Mayonnaise',12,15,'A small, rich two-yolk mayonnaise seasoned with mustard, vinegar and pepper.',[yolks(2),mustard(.25),vinegar(15),oil(150),salt(.25),pepper(.125)],emulsion(['yolks','mustard','vinegar','salt','pepper']),'The undefined teacup of oil becomes an explicit modern 150 ml. The saltspoon of dry mustard is interpreted as a quarter teaspoon. Seasoning amounts are supplied. Commercially pasteurized separated yolks replace the original shell-to-shell separation procedure.');eggsource(r)
r=add(2,'Canadian Three-Yolk Mayonnaise',12,20,'Three yolks give this small olive-oil mayonnaise a rich texture, balanced by vinegar.',[yolks(3),oil(140),vinegar(30),salt(.25)],['Whisk {{yolks}} and {{salt}} in a clean bowl set on a damp towel. Measure {{oil}} and {{vinegar}} into separate small jugs.','Whisk in a few drops of oil at a time until the yolks begin to thicken. Continue adding small amounts of the measured oil, alternating with a few drops of the measured vinegar, whisking each addition in completely.','Continue until all the oil and vinegar are incorporated and the mayonnaise is smooth and creamy. The gradual addition matters more than the original fixed half-hour beating time.',COLD],'The source gill of Lucca olive oil becomes an explicitly rounded modern 140 ml. Three yolks and two tablespoons vinegar are retained. Salt is supplied. The oil and vinegar are added alternately after the emulsion starts, preserving the original method.');eggsource(r)
r=add(3,'Cooked Butter and Cream Mayonnaise Dressing',30,90,'A cooked egg-and-vinegar dressing is enriched with butter and cream and finished with tarragon vinegar.',[I('eggs',2,'','large eggs','Use 100 g pasteurized liquid whole egg.'),vinegar(60,'malt'),I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a mild dressing.'),I('mustard',1,'tsp','prepared English mustard','Use the same volume of prepared Dijon mustard.'),I('butter',85,'g','unsalted butter, cut into small cubes','Use the same weight of a block-style dairy-free butter alternative; the cream still contains dairy.'),I('sugar',1,'tbsp','granulated sugar','Use the same volume of caster sugar.'),salt(1),I('cream',240,'ml','pasteurized heavy cream','Use the same volume of unsweetened plant cream suitable for cooking for a different flavor.'),I('tarragon',30,'ml','tarragon vinegar','Use the same volume of white wine vinegar.')],['Set a heatproof bowl over a saucepan of gently simmering water, with the bowl clear of the water. Whisk {{eggs}}, {{vinegar}}, {{cayenne}}, {{mustard}}, {{sugar}} and {{salt}} in the bowl.','Cook over the simmering water, stirring constantly and scraping the sides, for about 8–12 minutes until the mixture thickens and reaches 71°C (160°F). Do not boil the mixture.','Remove from the heat and gradually whisk in {{butter}} until melted and smooth. This step supplies the butter addition missing from the original method.','Set the bowl in a cold-water bath without letting water enter the dressing. Stir until cool, then cover and refrigerate promptly, within 2 hours, for about 45 minutes until cold.','Gradually whisk in cold {{cream}}, followed by {{tarragon}} a little at a time. Whisk for about 5 minutes until evenly blended.','Cover and refrigerate at 4°C (40°F) or colder. Use within 3 days, not the historical fortnight. Stir before serving in small portions.'],'A half-sized batch is used. The original scan says three-quarters cup butter and quarter-teaspoon cayenne, not the extracted half-cup butter and half-teaspoon cayenne. Half of the corrected butter quantity is supplied as 85 g. Mixed mustard is interpreted as prepared English mustard. Butter incorporation and a measured cooking endpoint are added. About 450–500 ml dressing is an estimate; chilling is included in total time.')
r=add(4,'Canadian Mustard Mayonnaise with Cream Option',15,15,'A mustard-seasoned olive-oil mayonnaise that can be lightened with freshly whipped cream.',[yolks(1),mustard(1),salt(.5),cayenne(),oil(180),vinegar(30)],emulsion(['yolks','mustard','salt','cayenne','vinegar']),'The original scan has three-quarters cup oil total and half-teaspoon salt. Its ingredient list and method refer to the same oil, not two additions. The source two tablespoons vinegar are included for a consistent dressing. The optional half-cup whipped cream is preserved as a complete variation.');eggsource(r)
vi=copy.deepcopy(r['ingredients'])+[I('cream',60,'ml','cold pasteurized heavy whipping cream','Use the same volume of unsweetened plant cream labeled for whipping; texture differs.')];vs=copy.deepcopy(r['steps']);vs[-1]='In a chilled bowl, whisk {{cream}} to soft peaks, about 2–3 minutes, making approximately 120 ml whipped cream. Fold gently into the finished mayonnaise. Use immediately; refrigerate any leftovers at 4°C (40°F) or colder and use within 1 day.';variant(r,'whipped-cream','Mayonnaise with whipped cream',vi,vs)
r=add(5,'Canadian Lemon and Vinegar Mayonnaise',18,15,'A two-yolk mayonnaise balances olive oil with equal amounts of lemon juice and vinegar.',[yolks(2),salt(.25),cayenne(),oil(240),vinegar(15),lemon(15)],emulsion(['yolks','salt','cayenne','vinegar','lemon']),'The full original paragraph specifies two yolks, a cup of oil and one tablespoon each vinegar and lemon. The longer mustard paragraph belongs to the next one-yolk recipe, so mustard is not added here. Acid is whisked in at the start as an explicit modern method choice. The optional repair is a small water-based re-emulsification rather than adding another raw yolk.');eggsource(r)
r=add(6,'Canadian One-Yolk Lemon Mayonnaise',17,15,'A mild, thick one-yolk mayonnaise uses a small amount of lemon and dry mustard.',[yolks(1),oil(240),salt(.5),lemon(2.5),cayenne(),mustard(.25),I('water',15,'ml','cold drinking water','Use the same volume of drinking water; extra lemon juice makes a tangier modern variation.')],emulsion(['yolks','salt','lemon','cayenne','mustard','water']),'The original scan gives a quarter-teaspoon mustard, half-teaspoon salt and half-teaspoon lemon juice. The mustard in the list and the later optional wording are the same quantity, not two additions. A tablespoon of cold water is supplied explicitly to make the very low-acid emulsion easier to form and less stiff. The small source lemon quantity is retained; it is not a preservation formula.');eggsource(r)
variant(r,'without-mustard','One-yolk mayonnaise without mustard',[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='mustard'],emulsion(['yolks','salt','lemon','cayenne','water']))
r=add(7,'Cooked Cream and Mustard Salad Dressing',14,75,'A small cooked yolk-and-cream dressing is sharply flavored with white-wine vinegar, mustard and pepper.',[yolks(3),I('cream',140,'ml','pasteurized heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.'),salt(.5),mustard(1),pepper(.5),vinegar(52.5)],['Whisk {{yolks}}, {{salt}}, {{mustard}}, {{pepper}} and {{vinegar}} in a heatproof bowl, then gradually whisk in {{cream}}.','Set the bowl over a pan of gently simmering water, without touching the water. Stir constantly for about 8–12 minutes until the dressing coats the back of a spoon and reaches 71°C (160°F). Keep the heat gentle and do not boil the dressing.','Remove from the heat. Set the bowl in a cold-water bath, keeping water out of the dressing, and stir until cool. Cover and refrigerate promptly, within 2 hours, for about 45 minutes until cold.','Stir before serving. Keep covered at 4°C (40°F) or colder and use within 3 days.'],'The original printed page371 gives quarter-pint cream, half-teaspoon salt and half-teaspoon pepper, correcting all three extracted amounts. Quarter pint is interpreted as an explicitly rounded Imperial-style 140 ml, not a verified universal pint conversion. Three yolks and 3½ tablespoons vinegar are retained. Gentle double-boiler cooking and a temperature endpoint replace the vague scalding instruction. Total time includes chilling.')

assert len(newids)==8,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full mayonnaise formula and method reviewed; original-page corrections, complete variants and refrigeration supplied','repair-batch-021.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))
